using ValveResourceFormat;using ValveResourceFormat.ResourceTypes;using ValveResourceFormat.Serialization.KeyValues;using ValveKeyValue;using System.Text.Json;
var root="work/lighting-sync";var reports=new List<object>();var template=root+"/installed-materials/materials/models/naige_bench_fix/normal.vmat_c";
foreach(var name in new[]{"naidan_body","naidan_body_outline","naidan_eye_outline","naidan_iris","naidan_mouth","naidan_pupil"}){
 using var r=new Resource();r.Read(template);var kv=(KeyValuesOrNTRO)r.DataBlock!;using var original=new Resource();original.Read(root+"/installed-materials/materials/models/naidan/"+name+".vmat_c");var before=((KeyValuesOrNTRO)original.DataBlock!).Data;
 string GetTexture(KVObject data,string key)=>data["m_textureParams"].Values.Single(x=>x["m_name"].ToString()==key)["m_pValue"].ToString();
 var oldColor=GetTexture(before,"g_tColor");var keys=new List<string>{"g_tColor"};if(name=="naidan_iris"||name=="naidan_pupil")keys.Add("g_tNormalRoughness");
 foreach(var key in keys){var v=before["m_textureParams"].Values.Single(x=>x["m_name"].ToString()==key)["m_pValue"];kv.Data["m_textureParams"].Values.Single(x=>x["m_name"].ToString()==key)["m_pValue"]=v;var reference=original.ExternalReferences!.ResourceRefInfoList.Single(x=>x.Name==v.ToString());if(!r.ExternalReferences!.ResourceRefInfoList.Any(x=>x.Id==reference.Id))r.ExternalReferences.ResourceRefInfoList.Add(reference);}
 foreach(var flag in kv.Data["m_intParams"].Values){if(flag["m_name"].ToString()=="F_SOLID_COLOR_OUTLINE")flag["m_nValue"]=0;}
 var ints=KVObject.Array();foreach(var f in kv.Data["m_intParams"].Values)if(f["m_name"].ToString()!="g_fVertexColorStrength1")ints.Add(f);kv.Data["m_intParams"]=ints;
 var strength=KVObject.Collection();strength.Add("m_name","g_fVertexColorStrength1");strength.Add("m_flValue",0f);kv.Data["m_floatParams"].Add(strength);
 kv.Data["m_materialName"]="materials/models/naidan/"+name+".vmat";
 var dest=root+"/stage/materials/models/naidan/"+name+".vmat_c";Directory.CreateDirectory(Path.GetDirectoryName(dest)!);using var data=new MemoryStream();kv.Serialize(data);using var refs=new MemoryStream();r.ExternalReferences!.Serialize(refs);ReplaceData(template,dest,new(){["DATA"]=data.ToArray(),["RERL"]=refs.ToArray()});
 using var check=new Resource();check.Read(dest);var d=((KeyValuesOrNTRO)check.DataBlock!).Data;var flags=d["m_intParams"].Values.ToDictionary(x=>x["m_name"].ToString(),x=>x["m_nValue"].ToInt32(null));if(flags["F_USE_NPR_LIGHTING"]!=1||flags["F_SOLID_COLOR_OUTLINE"]!=0||flags.GetValueOrDefault("F_SELF_ILLUM")!=0)throw new Exception("Wrong lighting flags");if(GetTexture(d,"g_tColor")!=oldColor)throw new Exception("Albedo changed");var rough=GetTexture(d,"g_tNormalRoughness");if(name=="naidan_body"&&rough!=GetTexture(((KeyValuesOrNTRO)r.DataBlock!).Data,"g_tNormalRoughness"))throw new Exception("Roughness changed unexpectedly");reports.Add(new{name,previousNpr=0,npr=1,albedoPreserved=oldColor,normalRoughness=rough,noSelfIllumination=true,existingOutlineGeometryRetained=true});
}
var manifest=JsonSerializer.Deserialize<Dictionary<string,string>>(File.ReadAllText("work/laugh-color-fix/merged-manifest.json"))!;foreach(var path in Directory.GetFiles(root+"/stage","*.vmat_c",SearchOption.AllDirectories)){using var r=new Resource();r.Read(path);foreach(var x in r.ExternalReferences!.ResourceRefInfoList)if(x.Name.EndsWith(".vtex")&&!x.Name.StartsWith("materials/default/")&&!manifest.ContainsKey(x.Name+"_c"))throw new Exception("Missing dependency "+x.Name);}
File.WriteAllText(root+"/lighting-validation.json",JsonSerializer.Serialize(reports,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("Body and face use bird NPR response; original albedo retained; body packed roughness matches bird; no emission. All texture dependencies exist in installed package.");
static void ReplaceData(string input,string output,Dictionary<string,byte[]> blocks){var raw=File.ReadAllBytes(input);int table=8+BitConverter.ToInt32(raw,8);int count=BitConverter.ToInt32(raw,12);using var ms=new MemoryStream();using var w=new BinaryWriter(ms);w.Write(raw,0,16);w.Write(new byte[count*12]);var entries=new List<(byte[] Tag,int At,int Len)>();for(int i=0;i<count;i++){int p=table+12*i;var tag=raw[p..(p+4)];int start=p+4+BitConverter.ToInt32(raw,p+4),length=BitConverter.ToInt32(raw,p+8);while(ms.Position%4!=0)w.Write((byte)0);int at=(int)ms.Position;var payload=blocks.GetValueOrDefault(System.Text.Encoding.ASCII.GetString(tag))??raw[start..(start+length)];w.Write(payload);entries.Add((tag,at,payload.Length));}ms.Position=0;w.Write((uint)ms.Length);ms.Position=8;w.Write(8);w.Write(count);for(int i=0;i<count;i++){int p=16+i*12;ms.Position=p;w.Write(entries[i].Tag);w.Write(entries[i].At-(p+4));w.Write(entries[i].Len);}File.WriteAllBytes(output,ms.ToArray());}
